/** Format human-readable relative time */
function formatRelativeTime(timestamp, t) {
    const diff = Date.now() - timestamp;
    if (diff < 60_000) {
        return t('justNow');
    }
    if (diff < 3600_000) {
        const mins = Math.max(1, Math.floor(diff / 60_000));
        return t('minutesAgo', { n: String(mins) });
    }
    if (diff < 86400_000) {
        const hours = Math.floor(diff / 3600_000);
        return t('hoursAgo', { n: String(hours) });
    }
    if (diff < 30 * 86400_000) {
        const days = Math.floor(diff / 86400_000);
        return t('daysAgo', { n: String(days) });
    }
    const d = new Date(timestamp);
    return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
}
/** Extract standard aspect ratio for precise filtering */
function getItemRatio(item) {
    if (item.aspectRatio && item.aspectRatio !== 'custom') {
        return item.aspectRatio;
    }
    if (item.output) {
        const ratioMatch = item.output.match(/\b(1:1|16:9|9:16|4:3|3:4|3:2|2:3)\b/);
        if (ratioMatch?.[1])
            return ratioMatch[1];
        const dimMatch = item.output.match(/(\d{3,4})\s*[×x*]\s*(\d{3,4})/);
        if (dimMatch?.[1] && dimMatch[2]) {
            const w = parseInt(dimMatch[1], 10);
            const h = parseInt(dimMatch[2], 10);
            if (w === h)
                return '1:1';
            const approx = w / h;
            if (Math.abs(approx - 16 / 9) < 0.05)
                return '16:9';
            if (Math.abs(approx - 9 / 16) < 0.05)
                return '9:16';
            if (Math.abs(approx - 4 / 3) < 0.05)
                return '4:3';
            if (Math.abs(approx - 3 / 4) < 0.05)
                return '3:4';
            if (Math.abs(approx - 3 / 2) < 0.05)
                return '3:2';
            if (Math.abs(approx - 2 / 3) < 0.05)
                return '2:3';
        }
    }
    return '1:1';
}
